<script setup>
import {computed,ref,watch,onUnmounted} from 'vue';import {Head,useForm} from '@inertiajs/vue3';
import AppLayout from '../Layouts/AppLayout.vue';import AppModal from '../Components/AppModal.vue';import FormErrors from '../Components/FormErrors.vue';import BrandIdentity from '../Components/BrandIdentity.vue';
const props=defineProps({settings:Object,defaults:Object});const softwareOpen=ref(false),appearanceOpen=ref(false),logoInput=ref(null),objectUrl=ref(null);
const software=useForm({section:'software',software_name:'',tagline:'',organization_name:'',footer_text:'',footer_note:'',login_heading:'',login_description:'',support_email:'',logo:null,remove_logo:false});
const appearance=useForm({section:'appearance',primary_color:'#2563eb',font_family:'system',font_size:15,corner_radius:10});
const colors=['#2563eb','#0284c7','#1d4ed8','#4f46e5','#7c3aed','#0f766e','#be185d','#334155'];
function showSoftware(){software.clearErrors();for(const key of ['software_name','tagline','organization_name','footer_text','footer_note','login_heading','login_description','support_email'])software[key]=props.settings[key]||'';software.logo=null;software.remove_logo=false;clearPreview();softwareOpen.value=true;}
function showAppearance(){appearance.clearErrors();for(const key of ['primary_color','font_family','font_size','corner_radius'])appearance[key]=props.settings[key];appearanceOpen.value=true;}
function clearPreview(){if(objectUrl.value)URL.revokeObjectURL(objectUrl.value);objectUrl.value=null;if(logoInput.value)logoInput.value.value='';}
function chooseLogo(event){const file=event.target.files?.[0];if(!file)return;if(objectUrl.value)URL.revokeObjectURL(objectUrl.value);objectUrl.value=null;software.logo=file;software.remove_logo=false;objectUrl.value=URL.createObjectURL(file);}
function removeLogo(){software.logo=null;software.remove_logo=true;clearPreview();}
function saveSoftware(){software.post('/settings',{forceFormData:true,preserveScroll:true,onSuccess:()=>{softwareOpen.value=false;software.logo=null;clearPreview();}});}
function saveAppearance(){appearance.post('/settings',{preserveScroll:true,onSuccess:()=>appearanceOpen.value=false});}
const previewBrand=computed(()=>({...props.settings,...software.data(),logo_url:software.remove_logo?null:objectUrl.value||props.settings.logo_url}));
const previewStyle=computed(()=>({'--preview-color':appearance.primary_color,'--preview-radius':appearance.corner_radius+'px',fontFamily:({system:'"Segoe UI",Arial,sans-serif',arial:'Arial,sans-serif',georgia:'Georgia,serif'})[appearance.font_family],fontSize:appearance.font_size+'px'}));
onUnmounted(clearPreview);
</script>
<template><Head title="Cấu hình phần mềm & giao diện"/><AppLayout><div class="page-heading"><div><div class="eyebrow">CÀI ĐẶT CHUNG</div><h1>Cấu hình phần mềm & giao diện</h1><p>Một bộ nhận diện dùng chung cho quản trị, đăng nhập và các cổng thi.</p></div></div><div class="notice">Thay đổi được lưu cho toàn hệ thống. Các cửa sổ đang mở nhận cấu hình mới khi chuyển trang hoặc tải lại.</div><div class="settings-grid"><section class="card"><div class="panel-title"><h2>Thông tin phần mềm</h2><button @click="showSoftware">Chỉnh sửa</button></div><div class="settings-brand"><BrandIdentity :settings="settings"/></div><dl class="settings-details"><div><dt>Đơn vị</dt><dd>{{settings.organization_name||'Chưa đặt'}}</dd></div><div><dt>Email hỗ trợ</dt><dd>{{settings.support_email||'Chưa đặt'}}</dd></div><div><dt>Footer</dt><dd>{{settings.footer_text||'Không hiển thị'}}<small class="cell-meta">{{settings.footer_note}}</small></dd></div></dl></section><section class="card"><div class="panel-title"><h2>Giao diện đồng bộ</h2><button @click="showAppearance">Đổi giao diện</button></div><div class="theme-summary"><span class="theme-color-chip" :style="{background:settings.primary_color}"/><div><strong>{{settings.primary_color.toUpperCase()}}</strong><small class="cell-meta">Màu chủ đạo toàn hệ thống</small></div></div><dl class="settings-details"><div><dt>Kiểu chữ</dt><dd>{{({system:'Hệ thống',arial:'Arial',georgia:'Georgia'})[settings.font_family]}}</dd></div><div><dt>Cỡ chữ</dt><dd>{{settings.font_size}} px</dd></div><div><dt>Bo góc</dt><dd>{{settings.corner_radius}} px</dd></div></dl></section></div><section class="card section-gap"><h2>Phạm vi áp dụng</h2><div class="settings-scope"><span>✓ Thanh menu & nhận diện</span><span>✓ Trang đăng nhập quản trị</span><span>✓ Cổng thi TOEIC, VSTEP, môn học</span><span>✓ Nút, biểu mẫu, modal & trạng thái chọn</span><span>✓ Tên trên tab trình duyệt & biểu tượng</span><span>✓ Footer & thông tin hỗ trợ</span></div></section>
<AppModal :open="softwareOpen" title="Cấu hình phần mềm" wide :busy="software.processing" @close="softwareOpen=false"><form @submit.prevent="saveSoftware"><FormErrors :errors="software.errors"/><div class="settings-brand-preview"><BrandIdentity :settings="previewBrand"/></div><div class="formgrid"><div class="field"><label for="setting-name">Tên phần mềm</label><input id="setting-name" v-model="software.software_name" required maxlength="80"/></div><div class="field"><label for="setting-tagline">Dòng mô tả dưới tên</label><input id="setting-tagline" v-model="software.tagline" required maxlength="100"/></div><div class="field"><label for="setting-org">Tên đơn vị / tổ chức</label><input id="setting-org" v-model="software.organization_name" maxlength="160"/></div><div class="field"><label for="setting-support">Email hỗ trợ</label><input id="setting-support" v-model="software.support_email" type="email" maxlength="255"/></div></div><div class="field"><label for="setting-logo">Logo (PNG, JPG hoặc WebP, tối đa 2 MB, 2048 × 2048)</label><input id="setting-logo" ref="logoInput" type="file" accept="image/png,image/jpeg,image/webp" @change="chooseLogo"/><div class="actions section-gap"><button type="button" class="secondary" @click="removeLogo">Dùng biểu tượng mặc định</button><span v-if="software.remove_logo" class="muted">Logo hiện tại sẽ được bỏ khi lưu.</span></div></div><div class="formgrid"><div class="field"><label for="setting-footer">Footer chính (để trống để ẩn)</label><input id="setting-footer" v-model="software.footer_text" maxlength="255"/></div><div class="field"><label for="setting-footer-note">Footer phụ (để trống để ẩn)</label><input id="setting-footer-note" v-model="software.footer_note" maxlength="255"/></div></div><div class="field"><label for="setting-heading">Lời chào trang đăng nhập</label><textarea id="setting-heading" v-model="software.login_heading" rows="3" required maxlength="250"/></div><div class="field"><label for="setting-description">Giới thiệu trang đăng nhập</label><textarea id="setting-description" v-model="software.login_description" rows="3" maxlength="600"/></div><div class="modal-actions"><button type="button" class="secondary" :disabled="software.processing" @click="softwareOpen=false">Hủy</button><button :disabled="software.processing">{{software.processing?'Đang lưu…':'Lưu cấu hình phần mềm'}}</button></div></form></AppModal>
<AppModal :open="appearanceOpen" title="Cấu hình giao diện" wide :busy="appearance.processing" @close="appearanceOpen=false"><form @submit.prevent="saveAppearance"><FormErrors :errors="appearance.errors"/><div class="settings-editor"><div><div class="field"><label for="setting-color">Màu chủ đạo</label><div class="color-inputs"><input id="setting-color" v-model="appearance.primary_color" type="color"/><input v-model="appearance.primary_color" aria-label="Mã màu chủ đạo" pattern="#[0-9A-Fa-f]{6}" required maxlength="7"/></div><div class="color-presets"><button v-for="color in colors" :key="color" type="button" class="color-swatch" :style="{background:color}" :aria-label="'Chọn màu '+color" :aria-pressed="appearance.primary_color===color" @click="appearance.primary_color=color"/></div></div><div class="field"><label for="setting-font">Kiểu chữ</label><select id="setting-font" v-model="appearance.font_family"><option value="system">Hệ thống (Segoe UI / Inter)</option><option value="arial">Arial</option><option value="georgia">Georgia</option></select></div><div class="formgrid"><div class="field"><label for="setting-font-size">Cỡ chữ (14–18 px)</label><input id="setting-font-size" v-model.number="appearance.font_size" type="number" min="14" max="18" required/></div><div class="field"><label for="setting-radius">Bo góc (4–16 px)</label><input id="setting-radius" v-model.number="appearance.corner_radius" type="number" min="4" max="16" required/></div></div><button type="button" class="secondary" @click="Object.assign(appearance,{primary_color:defaults.primary_color,font_family:defaults.font_family,font_size:defaults.font_size,corner_radius:defaults.corner_radius})">Chọn lại giao diện xanh mặc định</button></div><div class="appearance-preview" :style="previewStyle"><span class="eyebrow">XEM TRƯỚC</span><strong>{{settings.software_name}}</strong><div class="preview-menu">Ngân hàng câu hỏi</div><p>Màu, kiểu chữ và bo góc được áp dụng đồng bộ sau khi lưu.</p><div class="preview-field">Biểu mẫu nhập dữ liệu</div><span class="preview-button">Lưu thay đổi</span></div></div><div class="modal-actions"><button type="button" class="secondary" :disabled="appearance.processing" @click="appearanceOpen=false">Hủy</button><button :disabled="appearance.processing">{{appearance.processing?'Đang lưu…':'Lưu giao diện'}}</button></div></form></AppModal></AppLayout></template>
